test('v01014 model selects dialogue candidates without transcribing text or paragraph indices and collection preserves both sides',async()=>{const {ctx,bag,flags}=environment();bag['integrated-memory-v1:room1'].settings.detailed=true;bag['integrated-memory-v1:room1'].settings.batchMessages=10;flags.rangeMessages=[{id:'u',role:'user',content:'한서래 | "면회할 수 있어?"'},{id:'a',role:'assistant',content:'의료진 | "환자분은 지금 안쪽 침상에 계십니다."'}];let calls=0;flags.dialogueReviewResponse=input=>{calls++;assert(input.dialogueCandidates.every(c=>c.candidateNumber&&c.sourceSegmentNumbers.length));return {dialogues:input.dialogueCandidates.map(c=>({eventNumber:1,candidateNumber:c.candidateNumber,speaker:c.speaker,recipient:c.speaker==='의료진'?'서재헌':'의료진',channel:'spoken',time:'',text:'면회 가능 여부에 대한 문답',linkReason:'환자 면회 안내에 대한 질문과 답변'})),omittedDialogues:[]};};await ctx.testing.refresh();await ctx.testing.handle('fullRun');assert.equal(calls,1);const d=await ctx.testing.read('room1'),qs=d.records.filter(q=>q.kind==='quote');assert.equal(qs.length,2);assert(qs.some(q=>q.quote==='환자분은 지금 안쪽 침상에 계십니다.'&&q.quoteVerified));assert(qs.every(q=>q.eventId));assert(flags.modelSystems.some(s=>s.includes('candidateNumber로 선택하고 quote를 다시 쓰지 않는다')));ctx.cleanup();});
test('v01013 automatic collection resolves an owned reply quote despite constant wrong event paragraph one in a single call',async()=>{const {ctx,bag,flags}=environment();bag['integrated-memory-v1:room1'].settings.detailed=true;bag['integrated-memory-v1:room1'].settings.batchMessages=10;flags.rangeMessages=[{id:'a',role:'assistant',content:'서재헌 | "이제 가자."'},{id:'u',role:'user',content:'한서래 | "응. 나도 아마 못 잊을 거야."'}];let calls=0;flags.dialogueReviewResponse=input=>{calls++;return {dialogues:input.dialogueCandidates.map(c=>{const event=input.events.find(e=>e.sourceIds.includes(c.sourceId));return {eventNumber:event.eventNumber,quote:c.quote,speaker:c.speaker,recipient:c.speaker==='한서래'?'서재헌':'한서래',channel:'spoken',time:'',text:'배웅에 대한 작별 인사',linkReason:'같은 작별 사건의 발언',sourceSegmentNumbers:input.sourceSections.filter(p=>p.sourceId===c.sourceId).map(p=>p.segmentNumber),eventSourceSegmentNumbers:[1]};}),omittedDialogues:[]};};await ctx.testing.refresh();await ctx.testing.handle('fullRun');assert.equal(calls,1);assert.equal(flags.extractionInputs.length,1);assert.equal(flags.reviewInputs.length,1);const d=await ctx.testing.read('room1'),q=d.records.find(q=>q.quote==='응. 나도 아마 못 잊을 거야.');assert(q);assert.equal(q.eventSourceEvidence,undefined);assert(q.quoteLinkEvidence.some(p=>p.sourceId==='u'));assert.equal(q.quoteVerified,true);assert.equal(d.records.filter(r=>r.kind==='quote').length,2);ctx.cleanup();});
