test('host integration: extraction, semantic recall, coexistence and single-send failure handling',async()=>{
 const {ctx,bag,sent,flags}=environment();
 await ctx.testing.refresh();await ctx.testing.handle('collect');
 assert.equal(bag['integrated-memory-v1:room1'].records[0].quoteVerified,true);
 const generate=()=>ctx.fetch('/api/generate',{method:'POST',body:JSON.stringify({chatId:'room1',userMessage:'촬영장 대기실에서 쉰다',generationGuide:'사용자 기존 지침',other:42})});
 assert((await generate()).ok);assert.equal(sent.length,1);assert(sent[0].generationGuide.includes('눈 붙일 시간 나면 눈이나 붙여'));assert(sent[0].generationGuide.includes('사용자 기존 지침'));assert(sent[0].generationGuide.includes('기존 게시판 소재'));assert.equal(sent[0].other,42);
 flags.generationFail=true;await assert.rejects(generate(),/network failure/);assert.equal(sent.length,2);flags.generationFail=false;
 flags.modelFail=true;assert((await generate()).ok);assert.equal(sent.length,3);assert(!sent[2].generationGuide.includes('기억 서재'));flags.modelFail=false;
 flags.storageFail=true;assert((await generate()).ok);assert.equal(sent.length,4);flags.storageFail=false;
 // Request-object and continuation path preserve fields and still inject once.
 const request=new Request('http://marinara.test/api/generate',{method:'POST',body:JSON.stringify({chatId:'room1',continueMessageId:'a1',generationGuide:'계속 지침'})});
 assert((await ctx.fetch(request)).ok);assert.equal(sent.length,5);assert(sent[4].generationGuide.includes('계속 지침'));assert.equal(sent[4].continueMessageId,'a1');
 ctx.cleanup();
});
