test('lossless graph compression shrinks repeated snapshots and restores independent undo objects',async()=>{
 const {ctx}=environment();Object.assign(ctx,{CompressionStream,DecompressionStream});const d=C.empty();d.records=Array.from({length:90},(_,i)=>({id:'r'+i,kind:'event',text:require('node:crypto').randomBytes(500).toString('base64'),time:'2027-01-03 19:30',sourceIds:['m'+i]}));for(let i=0;i<4;i++)C.checkpoint(d);
 const packed=await ctx.testing.pack(d);assert.equal(packed.storageEncoding,'integrated-memory-gzip-dag-v2');const restored=await ctx.testing.unpack(packed);assert.equal(JSON.stringify(restored),JSON.stringify(d));restored.records[0].text='현재 수정';assert.notEqual(restored.undo[0].records[0].text,'현재 수정');
 const classic=Buffer.from(await new Response(new Blob([JSON.stringify(d)]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer()).toString('base64');assert(packed.payload.length<classic.length*.6);ctx.cleanup();
});
test('64-bit embedding storage preserves every numeric value exactly and keeps old indexes readable',async()=>{
 const {ctx}=environment();const vector=[Math.PI,Number.MIN_VALUE,-0,0.12345678901234567,1e-290,1e290],index={schema:1,connectionId:'conn1',anchor:vector,entries:{a:{hash:'h',vectors:[vector,vector]}}};const small=ctx.testing.compactIndex(index),restored=ctx.testing.expandIndex(small);assert.equal(small.vectorEncoding,'float64-le-v1');for(let i=0;i<vector.length;i++){assert(Object.is(restored.anchor[i],vector[i]));assert(Object.is(restored.entries.a.vectors[0][i],vector[i]));}assert.equal(ctx.testing.expandIndex(index),index);assert.throws(()=>ctx.testing.expandIndex({...small,anchor:'AA=='}),/길이/);ctx.cleanup();
});
test('storage optimization keeps all memory and user undo, removes only internal draft snapshots and isolates other rooms',async()=>{
 const {ctx,bag,flags,embeddingCalls}=environment();const d=bag['integrated-memory-v1:room1'];d.records=Array.from({length:50},(_,i)=>({id:'r'+i,kind:'event',text:'사건 '+i+' '+require('node:crypto').randomBytes(500).toString('base64'),time:'2027-01-03 19:30',sourceIds:['m'+i]}));d.processed={m1:'verified'};for(let i=0;i<4;i++)C.checkpoint(d);const original=C.clone(d);
 const anchor=C.vector(Array.from({length:256},(_,i)=>Math.sin(i+1)));const oldIndex={schema:1,connectionId:'conn1',anchor,entries:{r0:{hash:C.hash(C.embeddingText(d.records[0])),vectors:[anchor]}}};bag['integrated-memory-v1:room1:vectors']=C.clone(oldIndex);bag['integrated-memory-v1:room1:fullDraft']={mode:'full',batchMessageLimit:2,fingerprint:'f',scratch:C.clone(d)};bag['integrated-memory-v1:room2']={untouched:'다른 방 기억'};const other=JSON.stringify(bag['integrated-memory-v1:room2']);await ctx.testing.refresh();Object.assign(ctx,{CompressionStream,DecompressionStream});const before=JSON.stringify(bag).length;await ctx.testing.handle('optimizeStorage');const saved=await ctx.testing.read('room1');assert.equal(JSON.stringify(saved),JSON.stringify(C.normalize(original)));assert.equal(saved.undo.length,4);const draft=await ctx.testing.unpack(bag['integrated-memory-v1:room1:fullDraft']);assert.equal(draft.scratch.undo.length,0);assert.equal(draft.scratch.processed.m1,'verified');assert.equal(draft.batchMessageLimit,2);const index=await ctx.testing.loadIndex('room1',saved,anchor);assert.equal(JSON.stringify(index),JSON.stringify(oldIndex));assert.deepEqual(C.vectorRanks(saved,index,[anchor]).map(x=>[x.r.id,x.score]),C.vectorRanks(saved,oldIndex,[anchor]).map(x=>[x.r.id,x.score]));assert.equal(JSON.stringify(bag['integrated-memory-v1:room2']),other);assert(JSON.stringify(bag).length<before*.6);assert.equal(flags.rawCalls,undefined);assert.equal(embeddingCalls.length,0);ctx.cleanup();
});

test('429 during extraction waits and retries the same rejected request without losing batch coverage',async()=>{const {ctx,bag,flags}=environment();flags.rangeMessages=rangeMessages(8);flags.rateAtRaw=1;await ctx.testing.refresh();await ctx.testing.handle('fullRun');assert.equal(flags.rawCalls,2);assert.equal(flags.runIds[0],flags.runIds[1]);assert.deepEqual(flags.inputSizes,[8,8]);assert.equal(bag['integrated-memory-v1:room1'].records.filter(r=>r.kind==='event'&&!r.deleted).length,8);ctx.cleanup();});
test('persistent 429 is bounded and never becomes an unbounded request loop',async()=>{const {ctx,bag,flags}=environment();flags.rangeMessages=rangeMessages(4);flags.rateAlways=true;await ctx.testing.refresh();await assert.rejects(ctx.testing.handle('fullRun'),e=>e.code==='MEMORY_RATE_LIMIT');assert.equal(flags.rawCalls,4);assert.equal(bag['integrated-memory-v1:room1'].records.length,0);ctx.cleanup();});
test('cleanup interrupts a rate-limit wait before any rejected request is retried',async()=>{const {ctx,flags}=environment();flags.rangeMessages=rangeMessages(4);flags.rateAlways=true;flags.rateRetryAfter='60';await ctx.testing.refresh();const work=ctx.testing.handle('fullRun');for(let i=0;i<100&&!flags.rawCalls;i++)await new Promise(r=>setTimeout(r,2));assert.equal(flags.rawCalls,1);ctx.cleanup();await assert.rejects(work,e=>e.code==='MEMORY_CANCELLED');assert.equal(flags.rawCalls,1);});
test('SDK storage 429 errors use the shared bounded cooldown and safely retry a rejected save',async()=>{const {ctx,bag}=environment();await ctx.testing.refresh();const original=ctx.marinara.storage.patch;let attempts=0;ctx.marinara.storage.patch=async data=>{attempts++;if(attempts===1){const e=new Error('Storage update failed (429)');e.retryMs=1;throw e;}return original(data);};const d=await ctx.testing.read('room1');d.story='원문과 기억 유지';await ctx.testing.write('room1',d,0);assert.equal(attempts,2);assert.equal(bag['integrated-memory-v1:room1'].story,'원문과 기억 유지');assert.equal(bag['integrated-memory-v1:room1'].revision,1);ctx.cleanup();});
test('retry headers and observed generation limits control cooldown and request spacing',async()=>{const {ctx}=environment();assert.equal(ctx.testing.retryDelay(new Headers({'retry-after':'2'})),2250);assert(ctx.testing.retryDelay(new Headers({'retry-after':new Date(Date.now()+5000).toUTCString()}))>3000);assert(ctx.testing.retryDelay(new Headers({'ratelimit-reset':String(Math.ceil(Date.now()/1000)+3)}))>=3000);ctx.testing.observeRate('generate',Response.json({}, {headers:{'ratelimit-limit':'6000'}}));const started=Date.now();await ctx.testing.requestGate('generate');assert(Date.now()-started>=10);ctx.cleanup();});

test('successful response with zero remaining allowance pauses further requests until reset',async()=>{const {ctx}=environment();ctx.testing.observeRate('general',Response.json({}, {headers:{'ratelimit-limit':'600','ratelimit-remaining':'0','ratelimit-reset':String(Math.ceil(Date.now()/1000)+5)}}));let finished=false;const waiting=ctx.testing.requestGate('general').then(()=>{finished=true;});await new Promise(r=>setTimeout(r,5));assert.equal(finished,false);ctx.cleanup();await assert.rejects(waiting,e=>e.code==='MEMORY_CANCELLED');});

