test('repair focuses all unresolved originals together after full chronological context and correction names only those targets',async()=>{
 const {ctx,bag,flags}=environment();bag['integrated-memory-v1:room1'].settings.detailed=true;flags.rangeMessages=rangeMessages(10);flags.reviewDropsFirst=true;flags.reviewDropCount=3;flags.badRepairEvidence=true;await ctx.testing.refresh();await assert.rejects(ctx.testing.handle('fullRun'),/원문 누락 보완/);
 const input=flags.lastRepairInput,targets=flags.rangeMessages.slice(0,3).map(m=>m.id);assert.deepEqual(input.targetMessages.map(m=>m.sourceId),targets);assert.deepEqual(input.targetMessages.map(m=>m.source.content),flags.rangeMessages.slice(0,3).map(m=>m.content));assert.deepEqual(input.contextMessages.map(m=>m.id),flags.rangeMessages.map(m=>m.id));assert(!targets.includes(input.contextMessages.at(-1).id));assert.equal(input.newMessages,undefined);assert.deepEqual(input.validationCorrection.requiredTargetIds,targets);assert(Object.keys(input).indexOf('targetMessages')>Object.keys(input).indexOf('contextMessages'));
 const diag=ctx.testing.getDiagnostic();assert.equal(diag.inputLayout,'focused_repair');assert.deepEqual(Array.from(diag.requestTargetIds),targets);assert.equal(diag.sourceRange.ids.length,10);assert.equal(bag['integrated-memory-v1:room1'].records.length,0);
 flags.badRepairEvidence=false;await ctx.testing.handle('fullRun');assert.equal(flags.stageCalls.filter(s=>s==='상세 기억 추출').length,1);assert.equal(flags.stageCalls.filter(s=>s==='원문 대조').length,1);assert.equal(bag['integrated-memory-v1:room1'].detailAudit.reviewedMessages,10);ctx.cleanup();
});

