test('diagnostic copy writes the exact JSON and clipboard rejection exposes a selectable fallback',async()=>{
 const {ctx,bag,flags,nodes}=environment();bag['integrated-memory-v1:room1'].settings.detailed=true;flags.rangeMessages=rangeMessages(10);flags.invalidChapterUnit=true;await ctx.testing.refresh();await assert.rejects(ctx.testing.handle('fullRun'));let copied;
 ctx.navigator={clipboard:{writeText:async v=>{copied=v;}}};await ctx.testing.handle('modelDiagnosticCopy');assert.deepEqual(JSON.parse(copied),JSON.parse(JSON.stringify(ctx.testing.getDiagnostic())));
 ctx.navigator.clipboard.writeText=async()=>{throw Error('denied');};await ctx.testing.handle('modelDiagnosticCopy');assert(ctx.testing.getCopyState().status.includes('펼쳤습니다'));assert(!ctx.testing.getCopyState().status.includes('복사했습니다'));assert.deepEqual(JSON.parse(ctx.testing.getCopyState().text),JSON.parse(copied));ctx.cleanup();
});

