for(const bad of ['wrong-count','string-count','string-number','duplicate','zero','fraction'])test('historical numeric selection rejects '+bad,async()=>{
 const {ctx,bag,flags}=environment();flags.contextSelectOverride=i=>({reviewedPartCount:bad==='wrong-count'?i.partCount-1:bad==='string-count'?String(i.partCount):i.partCount,selectedPartNumbers:bad==='string-number'?['1']:bad==='duplicate'?[1,1]:bad==='zero'?[0]:bad==='fraction'?[1.5]:[]});
 await assert.rejects(ctx.testing.prepareReviewContext(bag['integrated-memory-v1:room1'],rangeMessages(10),[{id:'p',rowid:1,content:'원문 '.repeat(30000)}],{}),/reviewedPartCount|문단 번호/);assert.equal(ctx.testing.getDiagnostic().errorCode,'MEMORY_REFERENCES');const diag=ctx.testing.getDiagnostic();assert.equal(diag.contextSelectionWindow.partCount,flags.contextSelectInputs.at(-1).pastParts.length);assert.equal(diag.contextSelectionWindow.parts[0].partNumber,1);assert.equal(diag.contextSelectionWindow.parts[0].partId,'p:p1:part1');ctx.cleanup();
});

test('ranked historical candidates exceeding budget are packed as whole exact source parts without model retries',async()=>{
 const {ctx,bag,flags}=environment();flags.contextSelectOverride=i=>({reviewedPartCount:i.partCount,selectedPartNumbers:i.pastParts.map(p=>p.partNumber).reverse()});let cached;
 const before=[{id:'p',rowid:1,content:('과거 원문 '.repeat(100)+'\n\n').repeat(160)}],original=JSON.stringify(before);
 const result=await ctx.testing.prepareReviewContext(bag['integrated-memory-v1:room1'],rangeMessages(10),before,{}, {save:async p=>{cached=structuredClone(p);}});
 assert.equal(flags.rawCalls,flags.contextSelectInputs.length);assert.equal(flags.rawCalls,cached.done);assert(cached.selectionBudgets.some(w=>w.omittedPartIds.length));assert(JSON.stringify(result.messages).length<80000);assert.equal(JSON.stringify(before),original);
 for(let i=0;i<cached.selectionBudgets.length;i++){const w=cached.selectionBudgets[i],input=flags.contextSelectInputs[i],byId=new Map(input.pastParts.map(p=>[p.partId,p]));assert(w.selectedCharacters<=w.maxSelectedCharacters);const kept=w.rankedPartIds.filter(id=>!w.omittedPartIds.includes(id));assert.equal(kept[0],input.pastParts.at(-1).partId);assert.equal(w.selectedCharacters,kept.reduce((n,id)=>n+byId.get(id).text.length,0));for(const id of kept)assert(result.messages.some(m=>m.selectedPartIds.includes(id)&&m.content.includes(byId.get(id).text)));}
 const calls=flags.rawCalls;await ctx.testing.prepareReviewContext(bag['integrated-memory-v1:room1'],rangeMessages(10),before,{}, {cached});assert.equal(flags.rawCalls,calls);ctx.cleanup();
});

