function progressiveDialogueRows(input,candidates=input.dialogueCandidates){return candidates.map(c=>({candidateNumber:c.candidateNumber,eventNumber:input.events.find(e=>e.sourceIds.includes(c.sourceId))?.eventNumber||1,speaker:c.speaker,recipient:'상대방',channel:'spoken',time:'',text:'같은 통화의 서로 다른 질문과 답변을 원문 전체로 보존한다.',linkReason:'해당 사건의 질문과 직접 응답'}));}
function progressiveMessages(count){return Array.from({length:10},(_,i)=>({id:'progress_'+i,role:i%2?'user':'assistant',content:Array.from({length:Math.floor(count/10)+(i<count%10?1:0)},(_,j)=>(i%2?'한서래':'서재헌')+' | "'+i+'번 메시지의 '+j+'번째 실제 질문 또는 응답입니다."').join('\n\n')}));}
